package net.civeira.phylax.feature.access.usergroupmembership.application.policy;

import jakarta.enterprise.event.Observes;
import net.civeira.phylax.common.security.Actor;
import net.civeira.phylax.feature.access.usergroupmembership.application.visibility.UserGroupMembershipVisibilityCheck;

public class TenantAccessible {

  /**
   * @autogenerated VisibilityPolicyGenerator
   * @param filter
   */
  public void filterVisibles(@Observes UserGroupMembershipVisibilityCheck filter) {
    Actor actor = filter.getActor();
    if (!(actor.hasScope("platform:global_access"))) {
      filter.peek(fl -> fl.setUserTenantAccessible(actor.getTenant()));
    }
  }
}
